    public bool flac_disk_room(Settings state,string protectedPath,long incomingBytes,bool isNew)
    {
        string directoryPath=ProjectSettings.GlobalizePath("user://audio_cache").SimplifyPath();if(protectedPath.GetBaseDir().SimplifyPath()!=directoryPath)return false;using var parent=DirAccess.Open(directoryPath.GetBaseDir());if(parent==null||parent.IsLink(directoryPath.GetFile()))return false;using var directory=DirAccess.Open(directoryPath);if(directory==null||directory.IsLink(protectedPath.GetFile())||directory.ListDirBegin()!=Error.Ok)return false;var entries=new List<Settings>();long total=isNew?incomingBytes:0;int visited=0;bool valid=true;string name=directory.GetNext();while(name.Length>0){visited++;if(visited>4096){valid=false;break;}string stem=name.GetBaseName();if(!directory.CurrentIsDir()&&!directory.IsLink(name)&&name.GetExtension()=="wav"&&CacheStem.IsMatch(stem)){string path=directoryPath.PathJoin(name);var info=signature(path);if(Int(info,"size")<0){valid=false;break;}total+=Int(info,"size");entries.Add(new Settings {["path"]=path,["bytes"]=Int(info,"size"),["used"]=Int(Dict(state,"flac_used"),path),["modified"]=Int(info,"modified")});}name=directory.GetNext();}directory.ListDirEnd();if(!valid)return false;int count=entries.Count+(isNew?1:0);entries.Sort((first,last)=>{int used=Int(first,"used").CompareTo(Int(last,"used"));if(used!=0)return used;int modified=Int(first,"modified").CompareTo(Int(last,"modified"));return modified!=0?modified:string.CompareOrdinal(Text(first,"path"),Text(last,"path"));});foreach(var entry in entries){if(total<=512L*1024*1024&&count<=256)break;string path=Text(entry,"path");if(path==protectedPath)continue;if(DirAccess.RemoveAbsolute(path)!=Error.Ok)continue;total-=Int(entry,"bytes");count--;Dict(state,"flac_used").Remove(path);}return total<=512L*1024*1024&&count<=256;
    }
